<?php

declare(strict_types=1);

namespace Sahil\Storage;

/**
 * Result of a successful upload.
 *
 * The stored name is generated by the framework from server-detected
 * content, never derived from the client-supplied file name.
 */
final class StoredFile
{
    public function __construct(
        public readonly string $disk,
        public readonly string $path,
        public readonly string $storedName,
        public readonly string $originalName,
        public readonly int $size,
        public readonly string $mimeType,
        public readonly ?string $url = null,
    ) {
    }

    /** Absolute path to the stored file on disk. */
    public function fullPath(string $root): string
    {
        return rtrim($root, '/').'/'.$this->path;
    }

    /** The extension of the stored file (server-derived). */
    public function extension(): string
    {
        $extension = pathinfo($this->storedName, PATHINFO_EXTENSION);

        return strtolower((string) $extension);
    }
}
